package streaming

import "context"

// ServerStreamingClient is a generic interface for server-streaming RPC on the client side.
type ServerStreamingClient[Res any] interface {
	ClientStream
	// Recv receives a typed response message from the server.
	Recv(ctx context.Context) (*Res, error)
}

type serverStreamingClient[Res any] struct {
	ClientStream
}

func (s *serverStreamingClient[Res]) Recv(ctx context.Context) (*Res, error) {
	var res Res
	if err := s.ClientStream.RecvMsg(ctx, &res); err != nil {
		return nil, err
	}
	return &res, nil
}

// NewServerStreamingClient creates a typed server-streaming client wrapper.
func NewServerStreamingClient[Res any](st ClientStream) ServerStreamingClient[Res] {
	return &serverStreamingClient[Res]{ClientStream: st}
}

// ServerStreamingServer is a generic interface for server-streaming RPC on the server side.
type ServerStreamingServer[Res any] interface {
	ServerStream
	// Send sends a typed response message to the client.
	Send(ctx context.Context, res *Res) error
}

type serverStreamingServer[Res any] struct {
	ServerStream
}

func (s *serverStreamingServer[Res]) Send(ctx context.Context, res *Res) error {
	return s.ServerStream.SendMsg(ctx, res)
}

// NewServerStreamingServer creates a typed server-streaming server wrapper.
func NewServerStreamingServer[Res any](st ServerStream) ServerStreamingServer[Res] {
	return &serverStreamingServer[Res]{ServerStream: st}
}

// ClientStreamingClient is a generic interface for client-streaming RPC on the client side.
type ClientStreamingClient[Req, Res any] interface {
	ClientStream
	// Send sends a typed request message to the server.
	Send(ctx context.Context, req *Req) error
	// CloseAndRecv closes the send direction and receives the final response.
	CloseAndRecv(ctx context.Context) (*Res, error)
}

type clientStreamingClient[Req, Res any] struct {
	ClientStream
}

func (c *clientStreamingClient[Req, Res]) Send(ctx context.Context, req *Req) error {
	return c.ClientStream.SendMsg(ctx, req)
}

func (c *clientStreamingClient[Req, Res]) CloseAndRecv(ctx context.Context) (*Res, error) {
	if err := c.ClientStream.CloseSend(ctx); err != nil {
		return nil, err
	}
	var res Res
	if err := c.ClientStream.RecvMsg(ctx, &res); err != nil {
		return nil, err
	}
	return &res, nil
}

// NewClientStreamingClient creates a typed client-streaming client wrapper.
func NewClientStreamingClient[Req, Res any](st ClientStream) ClientStreamingClient[Req, Res] {
	return &clientStreamingClient[Req, Res]{ClientStream: st}
}

// ClientStreamingServer is a generic interface for client-streaming RPC on the server side.
type ClientStreamingServer[Req, Res any] interface {
	ServerStream
	// Recv receives a typed request message from the client.
	Recv(ctx context.Context) (*Req, error)
	// SendAndClose sends the final response and closes the stream.
	SendAndClose(ctx context.Context, res *Res) error
}

type clientStreamingServer[Req, Res any] struct {
	ServerStream
}

func (c *clientStreamingServer[Req, Res]) Recv(ctx context.Context) (*Req, error) {
	var req Req
	if err := c.ServerStream.RecvMsg(ctx, &req); err != nil {
		return nil, err
	}
	return &req, nil
}

func (c *clientStreamingServer[Req, Res]) SendAndClose(ctx context.Context, res *Res) error {
	return c.ServerStream.SendMsg(ctx, res)
}

// NewClientStreamingServer creates a typed client-streaming server wrapper.
func NewClientStreamingServer[Req, Res any](st ServerStream) ClientStreamingServer[Req, Res] {
	return &clientStreamingServer[Req, Res]{ServerStream: st}
}

// BidiStreamingClient is a generic interface for bidirectional streaming RPC on the client side.
type BidiStreamingClient[Req, Res any] interface {
	ClientStream
	// Send sends a typed request message to the server.
	Send(ctx context.Context, req *Req) error
	// Recv receives a typed response message from the server.
	Recv(ctx context.Context) (*Res, error)
}

type bidiStreamingClient[Req, Res any] struct {
	ClientStream
}

func (b *bidiStreamingClient[Req, Res]) Send(ctx context.Context, req *Req) error {
	return b.ClientStream.SendMsg(ctx, req)
}

func (b *bidiStreamingClient[Req, Res]) Recv(ctx context.Context) (*Res, error) {
	var res Res
	if err := b.ClientStream.RecvMsg(ctx, &res); err != nil {
		return nil, err
	}
	return &res, nil
}

// NewBidiStreamingClient creates a typed bidirectional streaming client wrapper.
func NewBidiStreamingClient[Req, Res any](st ClientStream) BidiStreamingClient[Req, Res] {
	return &bidiStreamingClient[Req, Res]{ClientStream: st}
}

// BidiStreamingServer is a generic interface for bidirectional streaming RPC on the server side.
type BidiStreamingServer[Req, Res any] interface {
	ServerStream
	// Recv receives a typed request message from the client.
	Recv(ctx context.Context) (*Req, error)
	// Send sends a typed response message to the client.
	Send(ctx context.Context, res *Res) error
}

type bidiStreamingServer[Req, Res any] struct {
	ServerStream
}

func (b *bidiStreamingServer[Req, Res]) Recv(ctx context.Context) (*Req, error) {
	var req Req
	if err := b.ServerStream.RecvMsg(ctx, &req); err != nil {
		return nil, err
	}
	return &req, nil
}

func (b *bidiStreamingServer[Req, Res]) Send(ctx context.Context, res *Res) error {
