// Package cep provides client-side endpoint types for streaming operations.
package cep

import (
	"context"

	"github.com/cloudwego/kitex/pkg/streaming"
)

// StreamEndpoint represents one stream call that returns a client stream.
type StreamEndpoint func(ctx context.Context) (st streaming.ClientStream, err error)

// StreamMiddleware wraps a StreamEndpoint with additional behavior.
type StreamMiddleware func(next StreamEndpoint) StreamEndpoint

// StreamMiddlewareBuilder builds a StreamMiddleware with information from a context.
type StreamMiddlewareBuilder func(ctx context.Context) StreamMiddleware

// StreamRecvEndpoint represents one stream recv call.
type StreamRecvEndpoint func(ctx context.Context, stream streaming.ClientStream, message interface{}) (err error)

// EqualsTo returns true if and only if both endpoints reference the same underlying function.
func (e StreamRecvEndpoint) EqualsTo(e2 StreamRecvEndpoint) bool {
	return &e == &e2
}

// StreamRecvMiddleware wraps a StreamRecvEndpoint with additional behavior.
type StreamRecvMiddleware func(next StreamRecvEndpoint) StreamRecvEndpoint

// StreamRecvMiddlewareBuilder builds a StreamRecvMiddleware with information from a context.
type StreamRecvMiddlewareBuilder func(ctx context.Context) StreamRecvMiddleware

// StreamSendEndpoint represents one stream send call.
type StreamSendEndpoint func(ctx context.Context, stream streaming.ClientStream, message interface{}) (err error)

// EqualsTo returns true if and only if both endpoints reference the same underlying function.
func (e StreamSendEndpoint) EqualsTo(e2 StreamSendEndpoint) bool {
	return &e == &e2
}

// StreamSendMiddleware wraps a StreamSendEndpoint with additional behavior.
type StreamSendMiddleware func(next StreamSendEndpoint) StreamSendEndpoint

// StreamSendMiddlewareBuilder builds a StreamSendMiddleware with information from a context.
type StreamSendMiddlewareBuilder func(ctx context.Context) StreamSendMiddleware

// StreamChain connects stream middlewares into one middleware (right-to-left composition).
func StreamChain(mws ...StreamMiddleware) StreamMiddleware {
	return func(next StreamEndpoint) StreamEndpoint {
		for i := len(mws) - 1; i >= 0; i-- {
			next = mws[i](next)
		}
		return next
	}
}

// StreamRecvChain connects stream recv middlewares into one middleware (right-to-left composition).
func StreamRecvChain(mws ...StreamRecvMiddleware) StreamRecvMiddleware {
	return func(next StreamRecvEndpoint) StreamRecvEndpoint {
		for i := len(mws) - 1; i >= 0; i-- {
			next = mws[i](next)
		}
		return next
	}
}

// StreamSendChain connects stream send middlewares into one middleware (right-to-left composition).
func StreamSendChain(mws ...StreamSendMiddleware) StreamSendMiddleware {
	return func(next StreamSendEndpoint) StreamSendEndpoint {
		for i := len(mws) - 1; i >= 0; i-- {
			next = mws[i](next)
		}
		return next
	}
}

// DummyStreamMiddleware is a dummy middleware that returns the next endpoint unchanged.
func DummyStreamMiddleware(next StreamEndpoint) StreamEndpoint {
	return next
}
