// Package transport provides predefined transport protocol.
package transport

import "strings"

// Protocol indicates the transport protocol.
type Protocol int

// Predefined transport protocols.
const (
	PurePayload Protocol = 0
	Framed      Protocol = 1 // Default protocol

	TTHeader Protocol = 1 << iota
	HTTP
	GRPC
	HESSIAN2
	STREAMING

	TTHeaderFramed      = TTHeader | Framed
	TTHeaderStreaming   = 64  // Dedicated value for TTHeader streaming
	GRPCStreaming       = 128 // Dedicated value for gRPC streaming
)

// Unknown indicates the protocol is unknown.
const Unknown = "Unknown"

// String prints human readable information.
func (tp Protocol) String() string {
	switch tp {
	case PurePayload:
		return "PurePayload"
	case Framed:
		return "Framed"
	case TTHeader:
		return "TTHeader"
	case HTTP:
		return "HTTP"
	case TTHeaderFramed:
		return "TTHeaderFramed"
	case GRPC:
		return "GRPC"
	case HESSIAN2:
		return "Hessian2"
	case TTHeaderStreaming:
		return "TTHeaderStreaming"
	case GRPCStreaming:
		return "GRPCStreaming"
	}

	// Handle composite values not explicitly enumerated
	var parts []string
	if tp&TTHeader != 0 {
		parts = append(parts, "TTHeader")
	}
	if tp&Framed != 0 {
		parts = append(parts, "Framed")
	}
	if tp&HTTP != 0 {
		parts = append(parts, "HTTP")
	}
	if tp&GRPC != 0 {
		parts = append(parts, "GRPC")
	}
	if tp&HESSIAN2 != 0 {
		parts = append(parts, "HESSIAN2")
	}
	if tp&STREAMING != 0 {
		parts = append(parts, "STREAMING")
	}

	if len(parts) > 0 {
		return strings.Join(parts, "|")
	}

	return Unknown
}
