// Dump returns diagnostic information about the connection pool.
// It provides visibility into pool size and active connections for debugging.
func (p *connPool) Dump() interface{} {
	type connInfo struct {
		Address     string
		Size        uint32
		ActiveConns int
	}

	var connections []connInfo
	p.conns.Range(func(addr, trans interface{}) bool {
		t := trans.(*transports)
		activeCount := 0
		for i := 0; i < int(t.size); i++ {
			if ct := t.cliTransports[i]; ct != nil {
				if active, ok := ct.(grpc.IsActive); ok && active.IsActive() {
					activeCount++
				}
			}
		}
		connections = append(connections, connInfo{
			Address:     addr.(string),
			Size:        t.size,
			ActiveConns: activeCount,
		})
		return true
	})

	return map[string]interface{}{
		"remote_service": p.remoteService,
		"pool_size":      p.size,
		"connections":    connections,
	}
}
