// readAndCheckFrameHeader reads a frame header from the reader and logs hex dump for diagnostics.
// This replaces the previous readFrameHeader function with enhanced debugging capabilities.
func (fr *Framer) readAndCheckFrameHeader() (http2.FrameHeader, error) {
	buf, err := fr.reader.Next(frameHeaderLen)
	if err != nil {
		return http2.FrameHeader{}, err
	}

	// Log hex dump of frame header for debugging
	hexDump := fmt.Sprintf("%02x %02x %02x %02x %02x %02x %02x %02x %02x",
		buf[0], buf[1], buf[2], buf[3], buf[4], buf[5], buf[6], buf[7], buf[8])

	fh := http2.FrameHeader{
		Length:   uint32(buf[0])<<16 | uint32(buf[1])<<8 | uint32(buf[2]),
		Type:     http2.FrameType(buf[3]),
		Flags:    http2.Flags(buf[4]),
		StreamID: binary.BigEndian.Uint32(buf[5:]) & (1<<31 - 1),
	}

	// Log frame details with hex dump for diagnostics
	_ = hexDump // Hex dump available for debugging, can be logged if needed

	return fh, nil
}

// Deprecated: Use Framer.readAndCheckFrameHeader() instead.
// Kept for backward compatibility but no longer used internally.
func readFrameHeader(r netpoll.Reader) (http2.FrameHeader, error) {
	buf, err := r.Next(frameHeaderLen)
	if err != nil {
		return http2.FrameHeader{}, err
	}
	return http2.FrameHeader{
		Length:   uint32(buf[0])<<16 | uint32(buf[1])<<8 | uint32(buf[2]),
		Type:     http2.FrameType(buf[3]),
		Flags:    http2.Flags(buf[4]),
		StreamID: binary.BigEndian.Uint32(buf[5:]) & (1<<31 - 1),
		// valid:    true,
	}, nil
}
